DROP TABLE IF EXISTS `payments`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `payments` (
  `payment_id` varchar(12) NOT NULL,
  `merchant_id` varchar(66) NOT NULL,
  `button_id` varchar(12) NOT NULL,
  `transaction_id` varchar(64) NOT NULL,
  `amount` bigint unsigned DEFAULT '0',
  `payer_id` varchar(255) DEFAULT NULL,
  `txid` varchar(64) DEFAULT NULL,
  `completed` tinyint(1) NOT NULL DEFAULT '0',
  `is_new` tinyint(1) NOT NULL DEFAULT '1',
  `blockchain_transaction` longtext,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `description` varchar(80) NOT NULL DEFAULT '',
  PRIMARY KEY (`payment_id`),
  KEY `payments_merchant_id_foreign` (`merchant_id`),
  KEY `idx_payments_button_id` (`button_id`),
  CONSTRAINT `payments_button_id_foreign` FOREIGN KEY (`button_id`) REFERENCES `payment_buttons` (`button_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `payments_merchant_id_foreign` FOREIGN KEY (`merchant_id`) REFERENCES `merchants` (`merchant_id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `payments_payment_id_foreign` FOREIGN KEY (`payment_id`) REFERENCES `ids` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

